'use strict';
const $=id=>document.getElementById(id), core=KanjiTestCore;
const files=(globalThis.QUESTION_BANK?.files||[]).map(f=>({...f,...core.parseFile(f.text,f.name)}));
let questions=[],responses=[],current=0,activeBlank=0,report=null,screen='setup',inputRefs=[];
const checked=new Set(files.filter(f=>!f.errors.length&&f.questions.length).map(f=>f.name));
function pool(){return core.unique(files.filter(f=>checked.has(f.name)).flatMap(f=>f.questions));}
function show(name){screen=name;for(const id of ['setup','test','results'])$(id).hidden=id!==name;window.scrollTo({top:0,behavior:'instant'});}
function refreshSettings(){const n=pool().length;const valid=Number($('question-count').value);$('question-count').max=String(n);$('pool-count').textContent=`${checked.size}ファイルを選択中・重複を除いて ${n} 問`;$('start').disabled=!n;$('select-all').textContent=checked.size===files.filter(f=>!f.errors.length&&f.questions.length).length?'選択を解除':'すべて選ぶ';$('setup-error').textContent=n&&(!Number.isSafeInteger(valid)||valid<1||valid>n)?`問題数は1〜${n}問で指定してください。`:'';}
function renderFiles(){const list=$('file-list');list.replaceChildren();for(const f of files){const label=document.createElement('label');label.className='file-option';const box=document.createElement('input');box.type='checkbox';box.checked=checked.has(f.name);box.disabled=!!f.errors.length||!f.questions.length;box.setAttribute('aria-label',f.title);box.onchange=()=>{if(box.checked)checked.add(f.name);else checked.delete(f.name);refreshSettings();};const info=document.createElement('span'),title=document.createElement('span'),name=document.createElement('small'),count=document.createElement('span');title.className='file-title';title.textContent=f.title;name.textContent=f.name;info.append(title,name);count.className='file-count';count.textContent=`${f.questions.length} 問`;label.append(box,info,count);list.append(label);}$('file-errors').textContent=files.flatMap(f=>f.errors).join('\n')||(!files.length?'問題ファイルを読み込めませんでした。問題一覧を生成してから再読み込みしてください。':'');refreshSettings();}
$('select-all').onclick=()=>{const available=files.filter(f=>!f.errors.length&&f.questions.length);if(available.every(f=>checked.has(f.name)))checked.clear();else available.forEach(f=>checked.add(f.name));renderFiles();};
$('question-count').addEventListener('input',refreshSettings);
for(const button of document.querySelectorAll('[data-count]'))button.onclick=()=>{$('question-count').value=button.dataset.count;refreshSettings();};
$('all-count').onclick=()=>{$('question-count').value=String(pool().length);refreshSettings();};
function begin(selected,label){questions=selected;responses=questions.map(q=>q.answers.map(()=>''));current=0;activeBlank=0;report=null;$('session-label').textContent=label;show('test');ink.setEnabled(true);renderQuestion();}
$('start').onclick=()=>{try{begin(core.sample(pool(),Number($('question-count').value)),'漢字テスト');}catch(e){$('setup-error').textContent=e.message;}};
function answered(i){return responses[i].every(v=>core.normalize(v));}
function answerCount(){return responses.reduce((n,_,i)=>n+Number(answered(i)),0);}
function progress(){const n=answerCount();$('answered-count').textContent=`回答済み ${n} / ${questions.length}`;$('progress').max=questions.length;$('progress').value=n;for(const [i,b]of Array.from($('question-map').children).entries())b.classList.toggle('done',answered(i));}
function sentence(container,q,mode='blank'){
 container.replaceChildren();for(const part of q.parts){if(part.text!==undefined){container.append(document.createTextNode(part.text));continue;}const j=part.blank,span=document.createElement('span');if(mode==='answer'){span.className='correct-answer';span.textContent=q.answers[j];container.append(span);}else{span.className='blank';span.textContent='□'.repeat(Array.from(q.answers[j]).length);span.setAttribute('aria-label',`空欄${j+1}`);if(q.hints[j]){const ruby=document.createElement('ruby'),rt=document.createElement('rt');rt.textContent=q.hints[j];ruby.append(span,rt);container.append(ruby);}else container.append(span);}}
}
function selectBlank(j){activeBlank=j;inputRefs.forEach((el,i)=>el.classList.toggle('active',i===j));}
function renderQuestion(){
 ink.reset();const q=questions[current];$('position').textContent=`${current+1} / ${questions.length} 問`;$('source-label').textContent=q.source;sentence($('question'),q);$('answer-fields').replaceChildren();inputRefs=[];activeBlank=0;
 q.answers.forEach((_,j)=>{const label=document.createElement('label');label.className='answer-label';label.append(document.createTextNode(q.answers.length===1?'あなたの回答':`空欄 ${j+1} の回答`));const input=document.createElement('input');input.type='text';input.autocomplete='off';input.spellcheck=false;input.setAttribute('autocapitalize','off');input.value=responses[current][j];input.placeholder=q.hints[j]?`「${q.hints[j]}」を漢字で`:'漢字で回答';input.onfocus=()=>selectBlank(j);input.addEventListener('input',()=>{responses[current][j]=input.value;progress();});label.append(input);$('answer-fields').append(label);inputRefs.push(input);});selectBlank(0);
 $('previous').disabled=current===0;$('next').textContent=current===questions.length-1?'採点に進む →':'次の問題 →';$('question-map').replaceChildren();questions.forEach((_,i)=>{const b=document.createElement('button');b.type='button';b.textContent=String(i+1);b.classList.toggle('current',i===current);b.setAttribute('aria-label',`第${i+1}問に移動`);if(i===current)b.setAttribute('aria-current','step');b.onclick=()=>{current=i;renderQuestion();};$('question-map').append(b);});progress();
}
function pick(c){if(screen!=='test')return;const input=inputRefs[activeBlank];if(!input)return;const start=input.selectionStart??input.value.length,end=input.selectionEnd??input.value.length;input.setRangeText(c,start,end,'end');responses[current][activeBlank]=input.value;progress();}
const ink=createInkPad({canvas:$('ink'),candidates:$('ink-candidates'),status:$('ink-status'),undo:$('ink-undo'),clear:$('ink-clear'),recognize:$('ink-recognize'),onPick:pick});
$('previous').onclick=()=>{if(current>0){current--;renderQuestion();}};$('next').onclick=()=>{if(current<questions.length-1){current++;renderQuestion();}else requestGrade();};
function requestGrade(){const remaining=questions.length-answerCount();$('grade-message').textContent=remaining?`未回答または空欄が残っている問題が${remaining}問あります。未回答は不正解になります。`:`全${questions.length}問の回答がそろいました。`;$('grade-dialog').showModal();}
$('finish').onclick=requestGrade;$('cancel-grade').onclick=()=>$('grade-dialog').close();
$('confirm-grade').onclick=()=>{$('grade-dialog').close();if(screen!=='test')return;report=core.grade(questions,responses);ink.setEnabled(false);renderResults();};
function renderResults(){
 show('results');$('result-title').textContent=report.correct===report.total?'全問正解、おめでとう！':'できた漢字を、確かめよう。';$('score').textContent=String(report.score);$('score-summary').textContent=`${report.total}問中 ${report.correct}問正解 ／ ${report.total-report.correct}問を復習`;$('retry-wrong').disabled=report.correct===report.total;$('result-list').replaceChildren();
 report.results.forEach((r,i)=>{const item=document.createElement('article');item.className='result-item';const meta=document.createElement('div');meta.className='result-meta';const badge=document.createElement('span');badge.className='result-badge'+(r.correct?'':' wrong');badge.textContent=r.correct?'○ 正解':'× 復習しよう';const source=document.createElement('span');source.textContent=`第${i+1}問 · ${r.question.source}`;meta.append(badge,source);const q=document.createElement('p');q.className='result-sentence';sentence(q,r.question,'answer');item.append(meta,q);r.question.answers.forEach((a,j)=>{const comparison=document.createElement('div');comparison.className='answer-comparison';const user=document.createElement('span');user.classList.toggle('wrong',!r.blanks[j]);user.textContent=`${r.question.answers.length>1?`空欄${j+1} `:''}あなたの回答：${r.values[j]||'（未回答）'}`;const correct=document.createElement('span');correct.textContent=`正解：${a}${r.question.hints[j]?`（${r.question.hints[j]}）`:''}`;comparison.append(user,correct);item.append(comparison);});$('result-list').append(item);});
}
$('retry-wrong').onclick=()=>{const wrong=report.results.filter(r=>!r.correct).map(r=>r.question);if(wrong.length)begin(core.sample(wrong,wrong.length),'まちがえた問題の復習');};
$('retry-all').onclick=()=>{show('setup');$('start').click();};$('back-setup').onclick=()=>show('setup');
window.addEventListener('beforeunload',e=>{if(screen==='test'&&responses.some(a=>a.some(v=>v.trim()))){e.preventDefault();e.returnValue='';}});
renderFiles();
